import "server-only";
import fs from "node:fs/promises";
import path from "node:path";
import { randomUUID } from "node:crypto";
import sharp from "sharp";
import { ServiceError } from "./common";

/**
 * Storage abstraction. The default driver writes to UPLOAD_DIR on a persistent disk.
 * To move to object storage (S3-compatible), implement the same three methods.
 * Keys are generated by the server only — never taken from user input.
 */
export interface Storage {
  put(key: string, data: Buffer): Promise<void>;
  get(key: string): Promise<Buffer | null>;
  remove(key: string): Promise<void>;
}

class LocalStorage implements Storage {
  constructor(private root: string) {}
  private resolve(key: string) {
    if (!/^[a-z0-9/_.-]+$/i.test(key) || key.includes("..")) throw new Error("invalid storage key");
    return path.join(this.root, key);
  }
  async put(key: string, data: Buffer) {
    const p = this.resolve(key);
    await fs.mkdir(path.dirname(p), { recursive: true });
    await fs.writeFile(p, data, { mode: 0o640 });
  }
  async get(key: string) {
    try { return await fs.readFile(this.resolve(key)); } catch { return null; }
  }
  async remove(key: string) {
    try { await fs.unlink(this.resolve(key)); } catch { /* already gone */ }
  }
}

let instance: Storage | null = null;
export function storage(): Storage {
  if (!instance) instance = new LocalStorage(path.resolve(process.cwd(), process.env.UPLOAD_DIR ?? "./uploads"));
  return instance;
}
export function setStorageForTests(s: Storage) { instance = s; }

/* ───── Images ───── */

export const IMAGE_MAX_BYTES = 12 * 1024 * 1024;
const IMAGE_FORMATS = new Set(["jpeg", "png", "webp", "avif", "heif"]);

/** Decodes the upload (rejecting anything that is not a real image), strips metadata (incl. GPS), and produces large + thumb WebP. */
export async function processPropertyImage(propertyId: number, input: Buffer) {
  if (input.length === 0) throw new ServiceError("فایل خالی است.");
  if (input.length > IMAGE_MAX_BYTES) throw new ServiceError("حجم هر عکس حداکثر ۱۲ مگابایت است.");
  let meta;
  try {
    meta = await sharp(input, { limitInputPixels: 50_000_000 }).metadata();
  } catch {
    throw new ServiceError("فایل یک عکس معتبر نیست.");
  }
  if (!meta.format || !IMAGE_FORMATS.has(meta.format)) throw new ServiceError("فقط عکس JPG، PNG، WebP یا HEIC پذیرفته می‌شود.");
  const base = sharp(input, { limitInputPixels: 50_000_000 }).rotate();
  const large = await base.clone().resize({ width: 1600, height: 1600, fit: "inside", withoutEnlargement: true }).webp({ quality: 80 }).toBuffer({ resolveWithObject: true });
  const thumb = await base.clone().resize({ width: 640, height: 480, fit: "cover" }).webp({ quality: 72 }).toBuffer();
  const id = randomUUID();
  const storageKey = `p/${propertyId}/${id}.webp`;
  const thumbKey = `p/${propertyId}/${id}_t.webp`;
  await storage().put(storageKey, large.data);
  await storage().put(thumbKey, thumb);
  return { storageKey, thumbKey, width: large.info.width, height: large.info.height };
}

/* ───── Private attachments (receipts, documents) ───── */

export const ATTACHMENT_MAX_BYTES = 10 * 1024 * 1024;
const SIGNATURES: { mime: string; ext: string; test: (b: Buffer) => boolean }[] = [
  { mime: "application/pdf", ext: "pdf", test: (b) => b.subarray(0, 5).toString("latin1") === "%PDF-" },
  { mime: "image/jpeg", ext: "jpg", test: (b) => b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff },
  { mime: "image/png", ext: "png", test: (b) => b.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])) },
  { mime: "image/webp", ext: "webp", test: (b) => b.subarray(0, 4).toString("latin1") === "RIFF" && b.subarray(8, 12).toString("latin1") === "WEBP" },
];

/** Validates by content signature (not by the client's declared type) and stores under a random key. */
export async function storeAttachment(input: Buffer) {
  if (input.length === 0) throw new ServiceError("فایل خالی است.");
  if (input.length > ATTACHMENT_MAX_BYTES) throw new ServiceError("حجم پیوست حداکثر ۱۰ مگابایت است.");
  const sig = SIGNATURES.find((x) => x.test(input));
  if (!sig) throw new ServiceError("فقط PDF، JPG، PNG یا WebP پذیرفته می‌شود.");
  const storageKey = `a/${randomUUID()}.${sig.ext}`;
  await storage().put(storageKey, input);
  return { storageKey, mime: sig.mime, size: input.length };
}
